// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(address caller) internal {
        bool reverted;
        bytes memory data = abi.encodeWithSelector(
            c.setL1BlockValues.selector,
            uint64(1), uint64(1), uint256(1), bytes32(0), uint64(1), bytes32(0), uint256(1), uint256(1)
        );
        try c.setL1BlockValues(uint64(1), uint64(1), uint256(1), bytes32(0), uint64(1), bytes32(0), uint256(1), uint256(1)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address depositor;
        try c.DEPOSITOR_ACCOUNT() returns (address __r) { depositor = __r; } catch { return; }
        assertTrue(reverted == (caller != depositor));
    }

    function testFuzz_run(address caller) public {
        vm.assume(uint160(caller) > 255 && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller);
    }

    receive() external payable {}
}
